/* Databases & Warehousing cards. Same fields as data/ps.js.
   SQL goes in q as <pre><code>…</code></pre> with &lt; &gt; escaped. */
(function(){
const R = String.raw;
addCards('db', [
/* ---------- ER model ---------- */
{id:'mn',t:'er',u:'ermodel',lv:1,k:'mcq',name:'Many-to-many relationships',sheet:R`\text{M:N relationship}\to\text{own relation with both entity keys (together the key)}`,
 q:R`Mapping an ER diagram to tables, a many-to-many relationship between Student and Course becomes:`,
 o:[R`A separate table whose key combines both entity keys`,R`A foreign key in the Student table`,R`A foreign key in the Course table`,R`Nothing; it is implied by the entity tables`],a:0,
 why:R`Neither side can hold a single foreign key, because each row relates to many on the other side. The relationship's own attributes go in that table too.`},
{id:'onen',t:'er',u:'ermodel',lv:1,k:'mcq',name:'One-to-many relationships',sheet:R`\text{1:N}\to\text{foreign key on the "many" side}`,
 q:R`Each employee works in exactly one department, and a department has many employees. The simplest mapping is:`,
 o:[R`Add the department's key as a foreign key in Employee`,R`Add the employee's key as a foreign key in Department`,R`Create a separate WorksIn table`,R`Merge both entities into one table`],a:0,
 why:R`Each employee row holds one department value, with no repetition problems. A foreign key in Department would need one column per employee.`},
{id:'multival',t:'er',u:'ermodel',lv:1,k:'mcq',name:'Multivalued attributes',sheet:R`\text{multivalued attribute}\to\text{separate relation (entity key, value)}`,
 q:R`An entity Person has a multivalued attribute PhoneNumbers. In a relational schema in 1NF, it becomes:`,
 o:[R`A separate table (PersonID, Phone), keyed on both columns`,R`One column holding a comma-separated list`,R`Several columns Phone1, Phone2, Phone3`,R`A derived attribute`],a:0,
 why:R`1NF needs atomic values, and a fixed number of columns can't hold an unbounded list. Derived attributes (like age from date of birth) are usually not stored at all.`},
{id:'weak',t:'er',u:'ermodel',lv:2,k:'mcq',name:'Weak entity sets',sheet:R`\text{weak entity: key = owner's key + partial key; total participation in identifying relationship}`,
 q:R`Which statement about a weak entity set is true?`,
 o:[R`Its tuples are identified by the owner's key together with its own partial key`,R`It has a primary key of its own`,R`It can exist without any owner entity`,R`Its participation in the identifying relationship is partial`],a:0,
 why:R`E.g. Dependent(name) of an Employee: names repeat across employees, so (EmpID, name) identifies a dependent. Every weak entity must have an owner.`},
{id:'ertables',t:'er',u:'ermodel',lv:2,k:'nat',name:'Counting relations from an ER model',sheet:R`\text{entity}\to1;\ \text{multivalued attr}\to+1;\ \text{M:N}\to+1;\ \text{1:N}\to0\ (\text{FK})`,
 q:R`Entities E1 (key A, plus one multivalued attribute M) and E2 (key B). A one-to-many relationship links each E2 to at most one E1. What is the minimum number of tables in a 3NF relational schema?`,n:{v:3},
 why:R`E1(A, …), E1_M(A, M) for the multivalued attribute, and E2(B, …, A) with A as a foreign key. A many-to-many relationship would need a fourth table.`},
{id:'onetoone',t:'er',u:'ermodel',lv:3,k:'mcq',name:'One-to-one with total participation',sheet:R`\text{1:1, total on one side: put the FK (or merge) on the total side}`,
 q:R`Every Manager manages exactly one Branch, and each Branch has at most one Manager. Where is the relationship best stored?`,
 o:[R`As a foreign key to Branch in the Manager table`,R`As a foreign key to Manager in the Branch table`,R`In a separate table`,R`It can't be represented`],a:0,
 why:R`Manager's participation is total, so its foreign key column is never NULL. Putting it in Branch would leave NULLs for branches without a manager.`},

/* ---------- Relational algebra ---------- */
{id:'selproj',t:'rel',u:'relalg',lv:1,k:'mcq',name:'Selection vs projection',sheet:R`\sigma_c(R):\ \text{rows satisfying }c;\ \ \pi_L(R):\ \text{columns }L,\ \text{duplicates removed}`,
 q:R`Which statement is correct in relational algebra?`,
 o:[R`σ picks rows; π picks columns and removes duplicate tuples`,R`σ picks columns; π picks rows`,R`π keeps duplicates`,R`σ can reduce the number of attributes`],a:0,
 why:R`Relations are sets, so projection removes duplicates. SQL's SELECT keeps them unless you write DISTINCT.`},
{id:'cross',t:'rel',u:'relalg',lv:1,k:'nat',name:'Cartesian product size',sheet:R`|R\times S|=|R|\cdot|S|,\ \ \text{degree}=\deg R+\deg S`,
 q:R`R has 3 attributes and 30 tuples; S has 2 attributes and 20 tuples. How many tuples are in \(R\times S\)?`,n:{v:600},
 why:R`Every pair of tuples: \(30\times20=600\), each with \(3+2=5\) attributes.`},
{id:'natjoin',t:'rel',u:'relalg',lv:1,k:'mcq',name:'Natural join',sheet:R`R(A,B)\bowtie S(B,C):\ \text{match on }B,\ \text{result }(A,B,C)`,
 q:R`\(R(A,B)\bowtie S(B,C)\) has attributes:`,
 o:[R`A, B, C`,R`A, B, B, C`,R`B only`,R`A and C only`],a:0,
 why:R`Natural join equates the common attributes and keeps one copy. With no common attributes it becomes the Cartesian product.`},
{id:'division',t:'rel',u:'relalg',lv:2,k:'nat',name:'Division',sheet:R`R(x,y)\div S(y)=\{x:\ \forall y\in S,\ (x,y)\in R\}`,
 q:R`Enrolled(student, course) = {(A, DB), (A, ML), (B, DB), (C, DB), (C, ML), (C, AI)} and Core(course) = {DB, ML}. How many tuples are in Enrolled ÷ Core?`,n:{v:2},
 why:R`Students enrolled in every core course: A and C. B lacks ML. Extra courses (C's AI) don't matter.`},
{id:'divbound',t:'rel',u:'relalg',lv:2,k:'mcq',name:'Size of a division result',sheet:R`|R\div S|\le|R|;\ \ S=\varnothing\Rightarrow R\div S=\pi_x(R)`,
 q:R`For \(X=R(x,y)\div S(y)\) with S non-empty, which is always true?`,
 o:[R`\(|X|\le|R|\)`,R`\(|X|\le|S|\)`,R`\(|X|\gt|R|\)`,R`\(|X|=|R|/|S|\)`],a:0,
 why:R`Each x in X contributes at least \(|S|\) tuples to R, so in fact \(|X|\cdot|S|\le|R|\). There's no bound in terms of \(|S|\) alone.`},
{id:'unioncomp',t:'rel',u:'relalg',lv:1,k:'cond',name:'Union compatibility',sheet:R`R\cup S,\ R\cap S,\ R-S\ \text{need same arity and compatible domains}`,
 q:R`Union, intersection and difference of R and S are defined only when:`,
 o:[R`R and S have the same number of attributes with compatible domains`,R`R and S share a key`,R`R and S have the same number of tuples`,R`R and S have no common attributes`],a:0,
 why:R`Tuples must be comparable position by position. Rename or project first if needed.`},
{id:'intersect',t:'rel',u:'relalg',lv:2,k:'fill',name:'Intersection from difference',sheet:R`R\cap S=R-(R-S)`,
 f:R`R\cap S=R-\boxed{\;?\;}`,
 o:[R`(R-S)`,R`(S-R)`,R`S`,R`(R\cup S)`],om:1,a:0,
 why:R`Remove from R everything not in S. Intersection isn't a basic operator because of this.`},
{id:'coverage',t:'rel',u:'relalg',lv:2,k:'mcq',name:'Checking containment',sheet:R`\pi_A(R)\subseteq\pi_A(S)\cup\pi_A(T)\iff\pi_A(R)-(\pi_A(S)\cup\pi_A(T))=\varnothing`,
 q:R`Relations Team(name, …), Batsman(name, …) and Bowler(name, …). Which expression checks that every name in Team is a batsman or a bowler?`,
 o:[R`\(\pi_{name}(Team)-(\pi_{name}(Batsman)\cup\pi_{name}(Bowler))=\varnothing\)`,R`\(\pi_{name}(Team)-(\pi_{name}(Batsman)\cap\pi_{name}(Bowler))=\varnothing\)`,R`\((\pi_{name}(Batsman)\cup\pi_{name}(Bowler))-\pi_{name}(Team)=\varnothing\)`,R`\(\pi_{name}(Team)\cap\pi_{name}(Batsman)=\varnothing\)`],a:0,
 why:R`"A ⊆ B" is "A − B is empty". Using ∩ would require each team member to be both. The third option checks the reverse containment.`},
{id:'outer',t:'rel',u:'relalg',lv:1,k:'mcq',name:'Left outer join',sheet:R`R\ \text{⟕}\ S:\ \text{all of }R,\ \text{NULLs where no match in }S`,
 q:R`A left outer join of R with S returns:`,
 o:[R`Every tuple of R, padded with NULLs when it has no match in S`,R`Only matching tuples`,R`Every tuple of S, padded with NULLs`,R`All tuples of both, unmatched ones padded`],a:0,
 why:R`The last option is the full outer join. The inner (natural or theta) join drops unmatched tuples.`},
{id:'selcascade',t:'rel',u:'relalg',lv:2,k:'mcq',name:'Equivalent expressions',sheet:R`\sigma_{c_1\wedge c_2}(R)=\sigma_{c_1}(\sigma_{c_2}(R));\ \ \sigma_c(R\bowtie S)=\sigma_c(R)\bowtie S\ \text{if }c\text{ uses only }R`,
 q:R`Which equivalence always holds?`,
 o:[R`\(\sigma_{c_1\wedge c_2}(R)=\sigma_{c_1}(\sigma_{c_2}(R))\)`,R`\(\pi_A(\pi_B(R))=\pi_B(R)\) for any A and B`,R`\(R-S=S-R\)`,R`\(\sigma_c(R\cup S)=\sigma_c(R)\cap\sigma_c(S)\)`],a:0,
 why:R`Selections cascade and commute, which lets optimisers push filters down early. Selection distributes over union as a union, not an intersection.`},
{id:'joinbound',t:'rel',u:'relalg',lv:2,k:'mcq',name:'Size of a join',sheet:R`0\le|R\bowtie S|\le|R|\cdot|S|;\ \text{FK to key join: }|R\bowtie S|\le|R|`,
 q:R`R.b is a foreign key referencing S's primary key b, and R.b is never NULL. The size of \(R\bowtie S\) is:`,
 o:[R`Exactly \(|R|\)`,R`Exactly \(|S|\)`,R`\(|R|\cdot|S|\)`,R`At most \(\min(|R|,|S|)\)`],a:0,
 why:R`Each R tuple matches exactly one S tuple, since the key is unique and the foreign key must exist.`},
{id:'trcform',t:'rel',u:'trc',lv:1,k:'mcq',name:'Tuple relational calculus',sheet:R`\{t\mid P(t)\}:\ \text{all tuples }t\text{ satisfying }P`,
 q:R`The TRC query \(\{t\mid t\in Emp\wedge t.salary>50000\}\) is equivalent to:`,
 o:[R`\(\sigma_{salary>50000}(Emp)\)`,R`\(\pi_{salary}(Emp)\)`,R`\(Emp\times Emp\)`,R`An unsafe query`],a:0,
 why:R`TRC says what to retrieve, not how. Safe TRC and relational algebra have the same expressive power.`},
{id:'trcexists',t:'rel',u:'trc',lv:2,k:'mcq',name:'∃ in TRC',sheet:R`\{t\mid t\in R\wedge\exists s\in S\,(t.A=s.A)\}=R\ltimes S`,
 q:R`\(\{t\mid t\in R\wedge\exists s\in S\,(t.A=s.A)\}\) returns:`,
 o:[R`The tuples of R that have at least one matching A value in S (a semi-join)`,R`All of \(R\times S\)`,R`The tuples of S matching R`,R`R minus S`],a:0,
 why:R`The output has only R's attributes. In algebra: \(\pi_{R}(R\bowtie S)\).`},
{id:'trcnat',t:'rel',u:'trc',lv:2,k:'nat',name:'Evaluating a TRC query',sheet:R`\exists s\in S(\dots):\ \text{keep }t\text{ if some }s\text{ satisfies the condition}`,
 q:R`R(P, Q) = {(1, a), (2, b), (3, c)} and S(P, V) = {(1, 5), (1, 7), (3, 0)}. How many tuples does \(\{t\mid t\in R\wedge\exists s\in S\,(s.P=t.P\wedge s.V>2)\}\) return?`,n:{v:1},
 why:R`P = 1 has V = 5 > 2, so it is kept, once (it's a set). P = 3 has only V = 0. P = 2 has no match.`},
{id:'trcforall',t:'rel',u:'trc',lv:3,k:'mcq',name:'∀ and division',sheet:R`\forall\ \text{in TRC}\leftrightarrow\div\ \text{in algebra}\leftrightarrow\text{NOT EXISTS … NOT EXISTS in SQL}`,
 q:R`A TRC query uses \(\forall c\in Course\ \exists e\in Enroll(\dots)\) to find students taking every course. In relational algebra this is naturally written with:`,
 o:[R`Division`,R`Union`,R`Left outer join`,R`Projection alone`],a:0,
 why:R`"For all" patterns are division. SQL has no division operator, so it uses double NOT EXISTS.`},
{id:'wherehaving',t:'rel',u:'sql',lv:1,k:'mcq',name:'WHERE vs HAVING',sheet:R`\text{WHERE filters rows before grouping; HAVING filters groups after}`,
 q:R`To keep only departments whose average salary exceeds 50,000, the condition <code>AVG(salary) > 50000</code> goes in:`,
 o:[R`HAVING`,R`WHERE`,R`ORDER BY`,R`FROM`],a:0,
 why:R`WHERE runs on single rows, before aggregates exist. HAVING runs on groups.`},
{id:'order',t:'rel',u:'sql',lv:2,k:'mcq',name:'Logical order of a SQL query',sheet:R`\text{FROM}\to\text{WHERE}\to\text{GROUP BY}\to\text{HAVING}\to\text{SELECT}\to\text{ORDER BY}`,
 q:R`In what logical order are the clauses of a SELECT query evaluated?`,
 o:[R`FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY`,R`SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY`,R`FROM, GROUP BY, WHERE, HAVING, SELECT, ORDER BY`,R`WHERE, FROM, SELECT, GROUP BY, HAVING, ORDER BY`],a:0,
 why:R`This is why a column alias defined in SELECT can't be used in WHERE, but can be used in ORDER BY.`},
{id:'countnull',t:'rel',u:'sql',lv:1,k:'mcq',name:'COUNT and NULL',sheet:R`\text{COUNT(*) counts rows; COUNT(col), SUM, AVG skip NULLs}`,
 q:R`A column has values 10, NULL, 20, NULL. What do <code>COUNT(*)</code> and <code>COUNT(col)</code> return?`,
 o:[R`4 and 2`,R`2 and 2`,R`4 and 4`,R`2 and 4`],a:0,
 why:R`COUNT(*) counts rows regardless of contents. Every other aggregate ignores NULLs.`},
{id:'avgnull',t:'rel',u:'sql',lv:2,k:'nat',name:'AVG with NULLs',sheet:R`\text{AVG(col)}=\frac{\text{SUM(col)}}{\text{COUNT(col)}}\ \text{(NULLs ignored)}`,
 q:R`A column holds 10, NULL, 20, 30. What does <code>AVG(col)</code> return?`,n:{v:20},
 why:R`NULLs are skipped: \((10+20+30)/3=20\). Dividing by 4 rows would give 15.`},
{id:'nulleq',t:'rel',u:'sql',lv:1,k:'mcq',name:'Comparing with NULL',sheet:R`\text{x = NULL is UNKNOWN; use IS NULL / IS NOT NULL}`,
 q:R`<code>SELECT * FROM T WHERE phone = NULL</code> returns:`,
 o:[R`No rows, because the comparison is UNKNOWN`,R`The rows where phone is missing`,R`All rows`,R`A syntax error in every DBMS`],a:0,
 why:R`Any comparison with NULL is UNKNOWN, and WHERE keeps only TRUE rows. Write <code>phone IS NULL</code>.`},
{id:'nestmax',t:'rel',u:'sql',lv:2,k:'nat',name:'Nested query with MAX',sheet:R`\text{scalar subquery computed once, then compared row by row}`,
 q:R`Loan(id, branch, amount) has rows (L1, A, 80), (L2, B, 45), (L3, B, 30), (L4, C, 60), (L5, A, 40), (L6, C, 50). How many rows does this return?<pre><code>SELECT id FROM Loan
WHERE amount > (SELECT MAX(amount) FROM Loan
                WHERE branch = 'B');</code></pre>`,n:{v:3},
 why:R`Branch B's maximum is 45. Amounts above 45: 80, 60, 50.`},
{id:'grouphaving',t:'rel',u:'sql',lv:1,k:'nat',name:'GROUP BY with HAVING',sheet:R`\text{one output row per group that passes HAVING}`,
 q:R`Emp(id, dept) has 3 rows with dept d1, 2 with d2 and 1 with d3. How many rows does this return?<pre><code>SELECT dept, COUNT(*) FROM Emp
GROUP BY dept HAVING COUNT(*) >= 2;</code></pre>`,n:{v:2},
 why:R`Groups d1 (3) and d2 (2) pass; d3 (1) doesn't.`},
{id:'corrsub',t:'rel',u:'sql',lv:3,k:'nat',name:'Correlated subqueries',sheet:R`\text{the inner query is re-evaluated for each outer row}`,
 q:R`Account(no, bal) has balances 10, 20, 20, 30, 40. How many rows does this return?<pre><code>SELECT no FROM Account A
WHERE (SELECT COUNT(*) FROM Account B WHERE A.bal &lt; B.bal)
   >= (SELECT COUNT(*) FROM Account C WHERE A.bal > C.bal);</code></pre>`,n:{v:3},
 why:R`For each row, compare the number of larger balances with the number of smaller ones. 10: 4 vs 0 yes. Each 20: 2 vs 1 yes. 30: 1 vs 3 no. 40: 0 vs 4 no. So 3 rows.`},
{id:'joincount',t:'rel',u:'sql',lv:1,k:'nat',name:'Join with filters',sheet:R`\text{FROM R, S WHERE join condition AND filters}`,
 q:R`Player(id, runs) = {(1, 50), (2, 30), (3, 70), (4, 20)} and Team(city, id) = {(Pune, 1), (Pune, 3), (Delhi, 2), (Pune, 4)}. How many rows does this return?<pre><code>SELECT * FROM Player P, Team T
WHERE P.id = T.id AND T.city = 'Pune' AND P.runs > 25;</code></pre>`,n:{v:2},
 why:R`Pune players are 1, 3 and 4; of these, 1 (50) and 3 (70) have more than 25 runs.`},
{id:'leftjoin',t:'rel',u:'sql',lv:2,k:'nat',name:'Row count of a LEFT JOIN',sheet:R`\text{LEFT JOIN rows}=\sum_{r\in R}\max(1,\#\text{matches of }r)`,
 q:R`R(id) = {1, 2, 3, 4} and S(id) = {1, 1, 3, 5}. How many rows does <code>SELECT * FROM R LEFT JOIN S ON R.id = S.id</code> return?`,n:{v:5},
 why:R`id 1 matches twice (2 rows), 3 matches once (1 row), and 2 and 4 have no match (1 NULL-padded row each). S's 5 is dropped.`},
{id:'notexists',t:'rel',u:'sql',lv:3,k:'mcq',name:'Double NOT EXISTS',sheet:R`\text{"x related to all y"}\equiv\text{NOT EXISTS y that x is NOT related to}`,
 q:R`What does this query return?<pre><code>SELECT s.name FROM Student s
WHERE NOT EXISTS (
  SELECT * FROM Course c
  WHERE NOT EXISTS (
    SELECT * FROM Enroll e
    WHERE e.sid = s.sid AND e.cid = c.cid));</code></pre>`,
 o:[R`Students enrolled in every course`,R`Students enrolled in no course`,R`Students enrolled in at least one course`,R`Courses with no students`],a:0,
 why:R`"There is no course that s is not enrolled in." This is SQL's way of writing relational division.`},
{id:'notexists2',t:'rel',u:'sql',lv:2,k:'mcq',name:'NOT EXISTS with a condition',sheet:R`\text{NOT EXISTS (… AND bad)}\equiv\text{all related rows are good}`,
 q:R`What does this return (assume every employee has at least one customer)?<pre><code>SELECT e.name FROM Employee e
WHERE NOT EXISTS (
  SELECT * FROM Customer c
  WHERE c.rep = e.id AND c.rating &lt;> 'GOOD');</code></pre>`,
 o:[R`Employees all of whose customers are rated GOOD`,R`Employees with at least one GOOD customer`,R`Employees with no GOOD customer`,R`Employees with exactly one GOOD customer`],a:0,
 why:R`It keeps e when no customer of e has a non-GOOD rating. Without the assumption, employees with no customers would also qualify, since nothing violates the condition.`},
{id:'union',t:'rel',u:'sql',lv:1,k:'mcq',name:'UNION vs UNION ALL',sheet:R`\text{UNION removes duplicates; UNION ALL keeps them}`,
 q:R`Query 1 returns 5 rows and query 2 returns 4 rows; 2 rows appear in both. How many rows does <code>Q1 UNION Q2</code> return (each query's rows are distinct)?`,
 o:[R`7`,R`9`,R`2`,R`5`],a:0,
 why:R`\(5+4-2=7\). UNION ALL would return 9.`},
{id:'distinct',t:'rel',u:'sql',lv:1,k:'mcq',name:'SQL keeps duplicates',sheet:R`\text{SELECT returns a multiset; DISTINCT removes duplicates}`,
 q:R`<code>SELECT city FROM Customer</code> on a table with 10 customers from 3 cities returns:`,
 o:[R`10 rows`,R`3 rows`,R`1 row`,R`It depends on the primary key`],a:0,
 why:R`SQL uses bag semantics. <code>SELECT DISTINCT city</code> would return 3 rows. Relational algebra's π removes duplicates automatically.`},

/* ---------- Keys & constraints ---------- */
{id:'keydefs',t:'ic',u:'keys',lv:1,k:'mcq',name:'Superkey vs candidate key',sheet:R`\text{superkey: determines all attributes; candidate key: minimal superkey}`,
 q:R`A candidate key is:`,
 o:[R`A superkey with no proper subset that is also a superkey`,R`Any set of attributes that includes the primary key`,R`An attribute that references another table`,R`Always a single attribute`],a:0,
 why:R`Minimality is the point. A relation can have several candidate keys; one is chosen as the primary key.`},
{id:'superkeys',t:'ic',u:'keys',lv:2,k:'nat',name:'Counting superkeys (two keys)',sheet:R`|\{\supseteq A\}\cup\{\supseteq B\}|=2^{n-1}+2^{n-1}-2^{n-2}`,
 q:R`R(A, B, C, D, E) has exactly two candidate keys, A and B. How many superkeys does it have?`,n:{v:24},
 why:R`Supersets of A: \(2^4=16\). Supersets of B: 16. Those containing both: \(2^3=8\). Inclusion–exclusion: \(16+16-8=24\).`},
{id:'superfd',t:'ic',u:'keys',lv:2,k:'nat',name:'Superkeys from FDs',sheet:R`\text{attributes never on a right-hand side must be in every key}`,
 q:R`R(A, B, C, D, E) with FDs A → B and C → D. How many superkeys does R have?`,n:{v:4},
 why:R`A, C and E never appear on a right side, so the only candidate key is ACE. Superkeys are ACE plus any subset of {B, D}: \(2^2=4\).`},
{id:'keyclosure',t:'ic',u:'keys',lv:2,k:'mcq',name:'Finding the candidate key',sheet:R`X\ \text{is a superkey}\iff X^+=\text{all attributes}`,
 q:R`R(A, B, C, D, E) with FDs A → B, BC → D, D → E. The candidate key(s):`,
 o:[R`AC only`,R`A only`,R`AC and BC`,R`ABC`],a:0,
 why:R`A and C never appear on a right side, so every key contains them, and \(AC^+=ABCDE\). ABC is a superkey but not minimal.`},
{id:'cyclekeys',t:'ic',u:'keys',lv:3,k:'nat',name:'Candidate keys with a cycle of FDs',sheet:R`A\to B\to C\to A:\ \text{any one of }A,B,C\text{ works in the key}`,
 q:R`R(A, B, C, D) with FDs A → B, B → C, C → A. How many candidate keys does R have?`,n:{v:3},
 why:R`D is never determined, so it is in every key. Each of A, B, C determines the other two, giving keys AD, BD and CD.`},
{id:'pknull',t:'ic',u:'keys',lv:1,k:'mcq',name:'Primary keys and NULL',sheet:R`\text{PK: unique and NOT NULL (entity integrity); FK may be NULL}`,
 q:R`Which statement is true?`,
 o:[R`A primary key can't be NULL, but a foreign key can`,R`A foreign key must be unique in its table`,R`A primary key may contain NULL once`,R`Every table must have a foreign key`],a:0,
 why:R`Entity integrity forbids NULL in the primary key. A NULL foreign key means "not related to anything", which is allowed unless declared NOT NULL.`},
{id:'fkdef',t:'ic',u:'fk',lv:1,k:'mcq',name:'Referential integrity',sheet:R`\text{FK value}\in\text{referenced key values, or NULL}`,
 q:R`Orders.cust_id is a foreign key referencing Customer.id. Referential integrity means:`,
 o:[R`Every non-NULL cust_id in Orders must exist as an id in Customer`,R`Every Customer must have an order`,R`cust_id must be unique in Orders`,R`Customer.id must be NULL-free and sorted`],a:0,
 why:R`The child (referencing) table may only point to existing parents.`},
{id:'fkviol',t:'ic',u:'fk',lv:2,k:'mcq',name:'Operations that may violate a foreign key',sheet:R`\text{can violate: insert/update child, delete/update parent;\ safe: delete child, insert parent}`,
 q:R`S.e is a foreign key referencing R's primary key. Which operation can NEVER violate this constraint?`,
 o:[R`Deleting a tuple from S`,R`Inserting a tuple into S`,R`Deleting a tuple from R`,R`Updating the key of a tuple in R`],a:0,
 why:R`Removing a referencing tuple can't leave a dangling reference. Inserting into R (the parent) is also always safe.`},
{id:'cascade',t:'ic',u:'fk',lv:2,k:'mcq',name:'ON DELETE CASCADE',sheet:R`\text{CASCADE: deleting a parent deletes its referencing children}`,
 q:R`Orders.cust_id references Customer.id with <code>ON DELETE CASCADE</code>. Deleting a customer:`,
 o:[R`Also deletes that customer's orders`,R`Is rejected if the customer has orders`,R`Sets those orders' cust_id to NULL`,R`Has no effect on Orders`],a:0,
 why:R`The second option is the default (RESTRICT/NO ACTION) and the third is ON DELETE SET NULL. Cascades can spread across several tables.`},
{id:'candidatepk',t:'ic',u:'keys',lv:2,k:'mcq',name:'Keys in a table definition',sheet:R`\text{UNIQUE/PRIMARY KEY columns are keys; other columns may repeat or be NULL}`,
 q:R`Customer(name, email PRIMARY KEY, phone, aadhaar REFERENCES Person(aadhaar)). Which statement is true?`,
 o:[R`phone may be NULL in Customer`,R`aadhaar is a candidate key of Customer`,R`email may be NULL`,R`aadhaar can't repeat in Customer`],a:0,
 why:R`Nothing constrains phone. A foreign key isn't automatically unique, so one aadhaar could appear in several Customer rows.`},

/* ---------- Normalisation ---------- */
{id:'armstrong',t:'norm',u:'fd',lv:1,k:'mcq',name:'Armstrong’s axioms',sheet:R`\text{reflexivity }(Y\subseteq X\Rightarrow X\to Y),\ \text{augmentation, transitivity}`,
 q:R`Which inference is NOT valid for functional dependencies?`,
 o:[R`AB → C implies A → C`,R`A → B implies AC → BC`,R`A → B and B → C imply A → C`,R`A → BC implies A → B`],a:0,
 why:R`You may split the right side (decomposition), never the left. City + street might determine pincode while city alone doesn't.`},
{id:'closure',t:'norm',u:'fd',lv:1,k:'nat',name:'Attribute closure',sheet:R`X^+:\ \text{start with }X;\ \text{add }B\text{ whenever }Y\to B\text{ and }Y\subseteq X^+`,
 q:R`R(A, B, C, D, E, F) with FDs A → B, B → C, CD → E. How many attributes are in \(\{A,D\}^+\)?`,n:{v:5},
 why:R`Start {A, D}; A → B adds B; B → C adds C; CD → E adds E. F is never reached, so the closure is ABCDE.`},
{id:'derive',t:'norm',u:'fd',lv:2,k:'mcq',name:'Testing whether an FD follows',sheet:R`X\to Y\ \text{follows}\iff Y\subseteq X^+`,
 q:R`FDs: A → B, A → C, CD → E, B → D. Which FD can be derived?`,
 o:[R`A → E`,R`B → E`,R`D → E`,R`C → E`],a:0,
 why:R`\(A^+\): A → B, C; B → D; CD → E. So A determines E. \(B^+=BD\), \(D^+=D\), \(C^+=C\).`},
{id:'fdinst',t:'norm',u:'fd',lv:2,k:'mcq',name:'FDs and table instances',sheet:R`\text{an instance can disprove an FD, but never prove it holds on the schema}`,
 q:R`In a table instance, X → Y appears violated when:`,
 o:[R`Two rows agree on X but differ on Y`,R`Two rows differ on X but agree on Y`,R`X has NULLs`,R`Y is a key`],a:0,
 why:R`An FD forbids the same X with different Y. Agreement on Y alone says nothing. An instance can show an FD fails, but only the schema's meaning shows it holds.`},
{id:'trivial',t:'norm',u:'fd',lv:1,k:'cond',name:'Trivial FDs',sheet:R`X\to Y\ \text{is trivial}\iff Y\subseteq X`,
 q:R`A functional dependency X → Y is trivial when:`,
 o:[R`Y is a subset of X`,R`X is a key`,R`X and Y are disjoint`,R`Y is a single attribute`],a:0,
 why:R`It holds in every instance. Normal-form tests only look at non-trivial FDs.`},
{id:'onenf',t:'norm',u:'nf',lv:1,k:'mcq',name:'First normal form',sheet:R`\text{1NF: every attribute value is atomic}`,
 q:R`A relation is in 1NF when:`,
 o:[R`Every attribute holds atomic (indivisible) values`,R`It has no partial dependencies`,R`It has no transitive dependencies`,R`Every determinant is a key`],a:0,
 why:R`A 1NF relation may still have a multi-attribute key and redundancy. Higher normal forms deal with those.`},
{id:'twonf',t:'norm',u:'nf',lv:2,k:'mcq',name:'Partial dependencies (2NF)',sheet:R`\text{2NF: no non-prime attribute depends on part of a candidate key}`,
 q:R`R(A, B, C, D) has key AB and FDs AB → C, B → D. The highest normal form R satisfies is:`,
 o:[R`1NF`,R`2NF`,R`3NF`,R`BCNF`],a:0,
 why:R`D (non-prime) depends on B, a part of the key: a partial dependency, so not 2NF.`},
{id:'threenf',t:'norm',u:'nf',lv:1,k:'cond',name:'Third normal form',sheet:R`\text{3NF: for each non-trivial }X\to A:\ X\text{ superkey, or }A\text{ prime}`,
 q:R`R is in 3NF when every non-trivial FD X → A satisfies:`,
 o:[R`X is a superkey, or A is part of some candidate key`,R`X is a superkey`,R`A is part of every candidate key`,R`X is a single attribute`],a:0,
 why:R`The "A is prime" escape clause is what separates 3NF from BCNF.`},
{id:'bcnf',t:'norm',u:'nf',lv:1,k:'cond',name:'Boyce–Codd normal form',sheet:R`\text{BCNF: every non-trivial }X\to Y\text{ has }X\text{ a superkey}`,
 q:R`A relation is in BCNF when, for every non-trivial FD X → Y:`,
 o:[R`X is a superkey`,R`Y is prime`,R`X is a candidate key and Y is non-prime`,R`X → Y is in the minimal cover`],a:0,
 why:R`Every determinant must be a key. This removes all FD-based redundancy, but may not preserve every dependency.`},
{id:'twoattr',t:'norm',u:'nf',lv:2,k:'mcq',name:'Two-attribute relations',sheet:R`\text{every relation with two attributes is in BCNF}`,
 q:R`Which statement is always true?`,
 o:[R`Every relation with two attributes is in BCNF`,R`Every 3NF relation is in BCNF`,R`No relation can be in both 3NF and BCNF`,R`A relation with a composite key is never in BCNF`],a:0,
 why:R`With attributes A and B, any non-trivial FD is A → B or B → A, which makes its left side a key. BCNF relations are always in 3NF too.`},
{id:'nf3notb',t:'norm',u:'nf',lv:3,k:'mcq',name:'3NF but not BCNF',sheet:R`\text{non-key determinant of a prime attribute}\Rightarrow\text{3NF, not BCNF}`,
 q:R`R(A, B, C) with FDs AB → C and C → B. R is:`,
 o:[R`In 3NF but not BCNF`,R`In BCNF`,R`In 2NF but not 3NF`,R`Not even in 2NF`],a:0,
 why:R`Candidate keys are AB and AC, so all attributes are prime. C → B has a non-superkey left side, which breaks BCNF, but B is prime, so 3NF holds.`},
{id:'transitive',t:'norm',u:'nf',lv:2,k:'mcq',name:'Transitive dependencies (3NF)',sheet:R`\text{key}\to X\to A,\ A\text{ non-prime}:\ \text{violates 3NF}`,
 q:R`Student(roll, dept, hod) with FDs roll → dept and dept → hod. The relation is:`,
 o:[R`In 2NF but not 3NF`,R`In 3NF`,R`In BCNF`,R`Not in 2NF`],a:0,
 why:R`The key, roll, is a single attribute, so there are no partial dependencies. But hod depends on roll through dept, a transitive dependency. Fix: split off Dept(dept, hod).`},
{id:'lossless',t:'norm',u:'decomp',lv:1,k:'cond',name:'Lossless-join test',sheet:R`R\to R_1,R_2\ \text{lossless}\iff R_1\cap R_2\to R_1\ \text{or}\ R_1\cap R_2\to R_2`,
 q:R`A decomposition of R into \(R_1\) and \(R_2\) is lossless exactly when:`,
 o:[R`The common attributes form a superkey of \(R_1\) or of \(R_2\)`,R`\(R_1\) and \(R_2\) have no common attributes`,R`Every FD is preserved`,R`\(R_1\) and \(R_2\) are both in BCNF`],a:0,
 why:R`Then joining back can't create spurious tuples. Disjoint relations can only be recombined by a Cartesian product, which is lossy.`},
{id:'lossy',t:'norm',u:'decomp',lv:2,k:'mcq',name:'Spotting a lossy decomposition',sheet:R`\text{common attribute not a key of either part}\Rightarrow\text{lossy}`,
 q:R`R(A, B, C) with only the FD A → B. Which decomposition is lossless?`,
 o:[R`(A, B) and (A, C)`,R`(A, B) and (B, C)`,R`(A) and (B, C)`,R`(A, C) and (B, C)`],a:0,
 why:R`The shared attribute A determines B, so it is a key of (A, B). In the others the shared attribute (B or C) determines nothing.`},
{id:'deppres',t:'norm',u:'decomp',lv:2,k:'mcq',name:'Dependency preservation',sheet:R`\text{3NF synthesis: lossless and dependency-preserving; BCNF: lossless, maybe not preserving}`,
 q:R`Which statement is true?`,
 o:[R`A lossless, dependency-preserving 3NF decomposition always exists; for BCNF it may not`,R`A BCNF decomposition always preserves dependencies`,R`Lossless decompositions always preserve dependencies`,R`3NF decompositions are always lossy`],a:0,
 why:R`Classic case: R(A, B, C) with AB → C and C → B. Any BCNF split loses AB → C.`},
{id:'deppjoin',t:'norm',u:'decomp',lv:2,k:'mcq',name:'Cost of losing a dependency',sheet:R`\text{FD spread across tables}\Rightarrow\text{checking it needs a join}`,
 q:R`A decomposition is not dependency-preserving. To enforce a lost FD on every update, the DBMS must frequently perform:`,
 o:[R`Joins`,R`Selections only`,R`Set unions`,R`Projections only`],a:0,
 why:R`The attributes of the lost FD now live in different tables, so they must be joined back to check it.`},

/* ---------- Files & indexing ---------- */
{id:'bfr',t:'file',u:'fileorg',lv:1,k:'nat',name:'Blocking factor',sheet:R`\text{bfr}=\lfloor B/R\rfloor,\ \ \#\text{blocks}=\lceil r/\text{bfr}\rceil`,
 q:R`Block size 4096 bytes, fixed-length records of 100 bytes (unspanned), 10,000 records. How many blocks does the file need?`,n:{v:250},
 why:R`\(\lfloor4096/100\rfloor=40\) records per block, so \(10000/40=250\) blocks.`},
{id:'heapfile',t:'file',u:'fileorg',lv:1,k:'mcq',name:'Heap (unordered) files',sheet:R`\text{heap: insert }O(1);\ \text{search }O(b)\text{ blocks}`,
 q:R`In an unordered (heap) file of b blocks, finding a record by a non-key attribute costs:`,
 o:[R`About b block reads (a full scan)`,R`About \(\log_2b\) block reads`,R`One block read`,R`\(b^2\) block reads`],a:0,
 why:R`With no order or index you must scan everything. Inserts are cheap: append to the last block.`},
{id:'sortedfile',t:'file',u:'fileorg',lv:1,k:'nat',name:'Binary search on a sorted file',sheet:R`\lceil\log_2b\rceil\ \text{block accesses}`,
 q:R`A file sorted on its key occupies 1024 blocks. About how many block accesses does a binary search on the key need in the worst case?`,n:{v:10},
 why:R`\(\log_21024=10\). Keeping the file sorted makes inserts expensive.`},
{id:'scanorg',t:'file',u:'fileorg',lv:2,k:'mcq',name:'Full scans',sheet:R`\text{full scan cheap for heap/sorted files; unclustered index scan: up to one I/O per record}`,
 q:R`Which way of reading all records of a table is usually the WORST for I/O?`,
 o:[R`Going through an unclustered index in key order`,R`Scanning a heap file`,R`Scanning a sorted file`,R`Scanning a clustered file`],a:0,
 why:R`Following an unclustered index jumps between blocks, often one I/O per record. A sequential scan reads each block once.`},
{id:'hashorg',t:'file',u:'fileorg',lv:1,k:'mcq',name:'Hash file organisation',sheet:R`\text{hashing: equality search }\approx O(1);\ \text{no help for range queries}`,
 q:R`A file is hashed on attribute A. Which query does it NOT help?`,
 o:[R`WHERE A BETWEEN 10 AND 20`,R`WHERE A = 15`,R`Inserting a record with A = 7`,R`Deleting the record with A = 9`],a:0,
 why:R`Hashing scatters nearby values, so a range needs a full scan. A B+ tree on A handles ranges.`},
{id:'denseidx',t:'file',u:'index',lv:1,k:'mcq',name:'Dense vs sparse indexes',sheet:R`\text{dense: entry per record;\ sparse: entry per block, needs a sorted file}`,
 q:R`A sparse index (one entry per data block) is possible only when:`,
 o:[R`The data file is sorted on the index key`,R`The index key is non-unique`,R`The index is secondary`,R`The file is a heap`],a:0,
 why:R`You find the right block by its first key, then search inside it, which only works if records are in key order. Secondary indexes must be dense.`},
{id:'bplus',t:'file',u:'index',lv:1,k:'mcq',name:'B+ tree structure',sheet:R`\text{B+: data pointers only at leaves; leaves linked for range scans}`,
 q:R`What makes B+ trees good for range queries?`,
 o:[R`All records are reached through the leaves, which are linked in key order`,R`Internal nodes store complete records`,R`They are always balanced binary trees`,R`They use hashing at the leaves`],a:0,
 why:R`Find the first key, then walk the leaf chain. A B tree also stores data pointers in internal nodes, so a range scan has to keep going back up the tree.`},
{id:'bporder',t:'file',u:'index',lv:2,k:'nat',name:'Order of a B+ tree node',sheet:R`\text{internal node: }p\cdot P+(p-1)\cdot K\le B`,
 q:R`Block size 1024 bytes, key 8 bytes, child pointer 8 bytes. What is the maximum number of child pointers in an internal B+ tree node?`,n:{v:64},
 why:R`\(8p+8(p-1)\le1024\Rightarrow16p\le1032\Rightarrow p=64\), holding 63 keys.`},
{id:'bpheight',t:'file',u:'index',lv:2,k:'nat',name:'B+ tree height',sheet:R`\text{levels}\approx\lceil\log_{\text{fanout}}(\#\text{leaves})\rceil+1`,
 q:R`A B+ tree indexes 1,000,000 records. Each leaf holds 100 entries and each internal node has up to 100 children. With every node full, how many levels does the tree have (leaves included)?`,n:{v:3},
 why:R`10,000 leaves; 100 internal nodes above them; 1 root above those. That gives three levels, so a lookup reads about 3 index blocks.`},
{id:'bpfill',t:'file',u:'index',lv:1,k:'mcq',name:'Minimum occupancy',sheet:R`\text{every node except the root is at least half full}`,
 q:R`In a B+ tree, the at-least-half-full rule is relaxed for:`,
 o:[R`Only the root`,R`All leaf nodes`,R`All internal nodes`,R`No node`],a:0,
 why:R`The root may hold a single key (two children). Splits and merges keep every other node at least half full.`},
{id:'hashvsb',t:'file',u:'index',lv:2,k:'mcq',name:'Choosing an index',sheet:R`\text{equality: hash or B+;\ range}(>,\lt,\text{BETWEEN}):\ \text{B+ tree}`,
 q:R`A query filters <code>Movie.rating > 3.4 AND Genre.name = 'Comedy'</code>. Which indexes suit these conditions?`,
 o:[R`A B+ tree on rating and a hash index on name`,R`A hash index on rating and a B+ tree on name`,R`Hash indexes on both`,R`No index can help`],a:0,
 why:R`The range condition needs ordered access (B+ tree). The equality condition can use either kind, and hashing is fine.`},
{id:'clustered',t:'file',u:'index',lv:2,k:'mcq',name:'Clustered indexes',sheet:R`\text{at most one clustered index per table (file order follows it)}`,
 q:R`How many clustered (clustering) indexes can a table have?`,
 o:[R`At most one`,R`One per candidate key`,R`One per attribute`,R`Unlimited`],a:0,
 why:R`A clustered index means the data file is physically ordered by its key, and a file has only one physical order. Secondary indexes can be many.`},

/* ---------- Data transformation ---------- */
{id:'scales',t:'dt',u:'dtypes',lv:1,k:'mcq',name:'Measurement scales',sheet:R`\text{nominal}\to\text{ordinal}\to\text{interval (no true zero)}\to\text{ratio (true zero)}`,
 q:R`Temperature in degrees Celsius is on which scale?`,
 o:[R`Interval`,R`Ratio`,R`Ordinal`,R`Nominal`],a:0,
 why:R`Differences are meaningful but 0 °C isn't "no temperature", so ratios like "twice as hot" are meaningless. Kelvin is a ratio scale.`},
{id:'ordinal',t:'dt',u:'dtypes',lv:1,k:'mcq',name:'Ordinal attributes',sheet:R`\text{ordinal: order matters, gaps don't; median and mode are meaningful}`,
 q:R`Customer satisfaction is recorded as poor, fair, good or excellent (in that order). Which summary is meaningful?`,
 o:[R`The median`,R`The mean`,R`The standard deviation`,R`The ratio of two values`],a:0,
 why:R`Ranks are ordered, but the gaps between them aren't measured, so arithmetic on the codes isn't meaningful.`},
{id:'discrete',t:'dt',u:'dtypes',lv:1,k:'mcq',name:'Nominal attributes',sheet:R`\text{nominal: labels only; only mode and equality are meaningful}`,
 q:R`Which attribute is nominal?`,
 o:[R`Blood group`,R`Height in cm`,R`Exam rank`,R`Year of birth`],a:0,
 why:R`Blood groups are categories with no order. Rank is ordinal; year is interval; height is ratio.`},
{id:'minmaxnat',t:'dt',u:'dtrans',lv:1,k:'nat',name:'Min–max normalisation',sheet:R`v'=\frac{v-\min}{\max-\min}(\text{new}_{\max}-\text{new}_{\min})+\text{new}_{\min}`,
 q:R`Income ranges from 12,000 to 98,000. Min–max normalise 73,600 to [0, 1], to 3 decimals.`,n:{v:0.7163,tol:0.002},
 why:R`\((73600-12000)/(98000-12000)=61600/86000\approx0.716\).`},
{id:'decscale',t:'dt',u:'dtrans',lv:2,k:'mcq',name:'Decimal scaling',sheet:R`v'=v/10^j,\ j\text{ smallest with }\max|v'|\lt1`,
 q:R`Values range from −986 to 917. With decimal scaling, −986 becomes:`,
 o:[R`−0.986`,R`−9.86`,R`−0.0986`,R`0`],a:0,
 why:R`The largest absolute value is 986, so j = 3: divide by 1000.`},
{id:'eqwidth',t:'dt',u:'dtrans',lv:1,k:'nat',name:'Equal-width binning',sheet:R`\text{width}=\frac{\max-\min}{k}`,
 q:R`Values in [0, 100] are split into 4 equal-width bins numbered 1–4. Which bin does 60 fall into?`,n:{v:3},
 why:R`Width 25: bins [0, 25), [25, 50), [50, 75), [75, 100]. 60 is in bin 3. Equal-frequency binning instead puts the same number of values in each bin.`},
{id:'smooth',t:'dt',u:'dtrans',lv:1,k:'nat',name:'Smoothing by bin means',sheet:R`\text{replace each value in a bin by the bin mean}`,
 q:R`A bin holds 4, 8, 15. After smoothing by bin means, what value replaces 15?`,n:{v:9},
 why:R`The mean is \(27/3=9\). Smoothing by bin boundaries would replace each value with the nearer of 4 and 15.`},
{id:'sampling',t:'dt',u:'dtrans',lv:2,k:'mcq',name:'Sampling for data reduction',sheet:R`\text{SRSWOR, SRSWR, cluster, stratified (keeps group proportions)}`,
 q:R`A dataset is 98% class A and 2% class B. Which sampling method guarantees that the sample keeps class B in proportion?`,
 o:[R`Stratified sampling`,R`Simple random sampling without replacement`,R`Simple random sampling with replacement`,R`Taking the first n records`],a:0,
 why:R`Sample within each class separately. A small random sample might contain no B at all.`},
{id:'reduce',t:'dt',u:'dtrans',lv:2,k:'mcq',name:'Kinds of data reduction',sheet:R`\text{dimensionality (PCA, wavelets, feature selection);\ numerosity (sampling, histograms, clustering);\ compression}`,
 q:R`Which is an example of dimensionality reduction rather than numerosity reduction?`,
 o:[R`Principal component analysis`,R`Random sampling of rows`,R`Replacing data with a histogram`,R`Clustering rows into representatives`],a:0,
 why:R`PCA reduces the number of attributes. The others reduce the number of rows or replace them with summaries.`},
{id:'lossycomp',t:'dt',u:'dtrans',lv:1,k:'mcq',name:'Lossless vs lossy compression',sheet:R`\text{lossless: exact reconstruction;\ lossy: approximate (e.g. PCA, wavelets)}`,
 q:R`Keeping only the top principal components of a dataset is:`,
 o:[R`Lossy compression`,R`Lossless compression`,R`Not compression at all`,R`Normalisation`],a:0,
 why:R`The discarded components can't be recovered, so reconstruction is approximate. Run-length or Huffman coding is lossless.`},

/* ---------- Data warehousing ---------- */
{id:'star',t:'dw',u:'schema',lv:1,k:'mcq',name:'Star schema',sheet:R`\text{star: one fact table + denormalised dimension tables}`,
 q:R`In a star schema:`,
 o:[R`A central fact table links directly to denormalised dimension tables`,R`Dimension tables are normalised into sub-dimensions`,R`Several fact tables share dimensions`,R`There are no foreign keys`],a:0,
 why:R`The second option is a snowflake schema; the third is a fact constellation (galaxy).`},
{id:'snow',t:'dw',u:'schema',lv:1,k:'mcq',name:'Snowflake schema',sheet:R`\text{snowflake: dimensions normalised (less redundancy, more joins)}`,
 q:R`Compared with a star schema, a snowflake schema:`,
 o:[R`Normalises dimension tables, saving space but needing more joins`,R`Has no fact table`,R`Denormalises the fact table`,R`Can't hold hierarchies`],a:0,
 why:R`E.g. Location splits into City → State tables. Queries pay for the extra joins.`},
{id:'galaxy',t:'dw',u:'schema',lv:1,k:'mcq',name:'Fact constellation',sheet:R`\text{fact constellation (galaxy): multiple fact tables sharing dimension tables}`,
 q:R`A warehouse has a Sales fact table and a Shipping fact table that both use the Time and Product dimensions. This is a:`,
 o:[R`Fact constellation (galaxy) schema`,R`Star schema`,R`Snowflake schema`,R`Normalised OLTP schema`],a:0,
 why:R`Shared (conformed) dimensions let you analyse across business processes.`},
{id:'facttab',t:'dw',u:'schema',lv:1,k:'mcq',name:'What a fact table holds',sheet:R`\text{fact table: numeric measures + foreign keys to dimensions}`,
 q:R`A fact table typically contains:`,
 o:[R`Numeric measures and foreign keys to the dimension tables`,R`Descriptive text about products`,R`Only primary keys of dimensions, with no measures`,R`The concept hierarchy`],a:0,
 why:R`E.g. (time_key, product_key, store_key, units_sold, revenue). Descriptions live in the dimension tables.`},
{id:'hierex',t:'dw',u:'hier',lv:1,k:'mcq',name:'Concept hierarchies',sheet:R`\text{e.g. street}\lt\text{city}\lt\text{state}\lt\text{country};\ \text{day}\lt\text{month}\lt\text{quarter}\lt\text{year}`,
 q:R`Which is a concept hierarchy for a location dimension, from low to high?`,
 o:[R`city → state → country`,R`country → state → city`,R`city → year → state`,R`product → brand → city`],a:0,
 why:R`Moving up a hierarchy is roll-up; moving down is drill-down.`},
{id:'cuboids',t:'dw',u:'hier',lv:2,k:'nat',name:'Number of cuboids with hierarchies',sheet:R`\#\text{cuboids}=\prod_{i=1}^{n}(L_i+1)`,
 q:R`A data cube has 3 dimensions whose hierarchies have 3, 2 and 4 levels (not counting "all"). How many cuboids are there?`,n:{v:60},
 why:R`Each dimension can be at any of its levels or at "all": \(4\times3\times5=60\).`},
{id:'cuboids0',t:'dw',u:'hier',lv:1,k:'nat',name:'Cuboids without hierarchies',sheet:R`n\ \text{dimensions, no hierarchies}:\ 2^n\ \text{cuboids}`,
 q:R`A data cube has 4 dimensions and no hierarchies. How many cuboids (including the apex) are there?`,n:{v:16},
 why:R`Each dimension is either grouped on or not: \(2^4=16\), from the base cuboid down to the apex (all).`},
{id:'rollup',t:'dw',u:'olap',lv:1,k:'mcq',name:'Roll-up and drill-down',sheet:R`\text{roll-up: climb a hierarchy (coarser);\ drill-down: descend (finer)}`,
 q:R`A report showing sales per (product, day, city) is changed to show sales per (product, month, city). This OLAP operation is:`,
 o:[R`Roll-up`,R`Drill-down`,R`Slice`,R`Pivot`],a:0,
 why:R`Day → month climbs the time hierarchy and aggregates. Going from country to state would be drill-down.`},
{id:'slicedice',t:'dw',u:'olap',lv:1,k:'mcq',name:'Slice and dice',sheet:R`\text{slice: fix one dimension;\ dice: select on two or more;\ pivot: rotate axes}`,
 q:R`Selecting the sub-cube where time = Q1 (one dimension fixed) is called:`,
 o:[R`Slice`,R`Dice`,R`Roll-up`,R`Pivot`],a:0,
 why:R`Dice applies conditions on two or more dimensions. Pivot only reorients the view.`},
{id:'cube',t:'dw',u:'olap',lv:2,k:'nat',name:'GROUP BY CUBE',sheet:R`\text{CUBE}(D_1,D_2):\ |D_1||D_2|+|D_1|+|D_2|+1\ \text{rows (all combinations present)}`,
 q:R`Facts(D1, D2, val): D1 takes 4 values, D2 takes 3, and every combination occurs. How many rows does this return?<pre><code>SELECT D1, D2, SUM(val) FROM Facts
GROUP BY CUBE (D1, D2);</code></pre>`,n:{v:20},
 why:R`Groupings (D1, D2): 12; (D1): 4; (D2): 3; (): 1. Total 20.`},
{id:'rollupsql',t:'dw',u:'olap',lv:2,k:'nat',name:'GROUP BY ROLLUP',sheet:R`\text{ROLLUP}(D_1,D_2):\ \text{groupings }(D_1,D_2),(D_1),()`,
 q:R`Same Facts table (D1 has 4 values, D2 has 3, all combinations present). How many rows does <code>GROUP BY ROLLUP (D1, D2)</code> return?`,n:{v:17},
 why:R`ROLLUP only removes columns from the right: \(12+4+1=17\). It skips the (D2)-only grouping that CUBE adds.`},
{id:'olapoltp',t:'dw',u:'olap',lv:1,k:'mcq',name:'OLAP vs OLTP',sheet:R`\text{OLTP: many short updates, normalised;\ OLAP: complex read-mostly analysis, historical}`,
 q:R`Which describes OLAP rather than OLTP?`,
 o:[R`Complex read-mostly queries over large amounts of historical data`,R`Many short insert and update transactions`,R`Highly normalised current data`,R`Strict per-transaction response times for clerks`],a:0,
 why:R`Warehouses are loaded in batches and optimised for aggregation, often with denormalised star schemas.`},
{id:'measures',t:'dw',u:'measures',lv:1,k:'mcq',name:'Holistic measures',sheet:R`\text{distributive: sum, count, min, max;\ algebraic: avg, std;\ holistic: median, mode, rank}`,
 q:R`Which measure is holistic (can't be computed from a fixed-size summary of each partition)?`,
 o:[R`Median`,R`Sum`,R`Average`,R`Maximum`],a:0,
 why:R`To merge medians you need all the values. Sum and max combine directly (distributive); average combines from (sum, count) pairs (algebraic).`},
{id:'algebraic',t:'dw',u:'measures',lv:2,k:'mcq',name:'Algebraic measures',sheet:R`\text{algebraic: computed from a fixed number of distributive measures}`,
 q:R`Why is AVG called an algebraic measure?`,
 o:[R`It can be computed from two distributive measures, SUM and COUNT, of each partition`,R`It is the sum of the partition averages`,R`It needs every individual value`,R`It is the same as the median`],a:0,
 why:R`Averaging the partition averages is wrong when partitions differ in size. Combine the sums and counts instead.`},
{id:'distrib',t:'dw',u:'measures',lv:1,k:'mcq',name:'Distributive measures',sheet:R`f(\text{all})=g\big(f(\text{part}_1),\dots,f(\text{part}_k)\big)`,
 q:R`Which measure is distributive?`,
 o:[R`COUNT`,R`AVG`,R`Median`,R`Standard deviation`],a:0,
 why:R`Total count = sum of partition counts. Standard deviation is algebraic (it needs count, sum and sum of squares).`},

/* ---------- Multiple select (MSQ) ---------- */
{id:'msqnf',t:'norm',u:'nf',lv:2,k:'msq',name:'Normal-form facts',sheet:R`\text{BCNF}\subset\text{3NF}\subset\text{2NF}\subset\text{1NF}`,
 q:R`Which statements are true?`,
 o:[R`Every relation in BCNF is in 3NF`,R`Every relation in 3NF is in BCNF`,R`Every relation with exactly two attributes is in BCNF`,R`1NF requires attribute values to be atomic`],a:[0,2,3],
 ex:[R`BCNF is the stricter condition.`,R`AB → C, C → B is 3NF but not BCNF.`,R`Any non-trivial FD there has a key on its left.`,R`Definition of 1NF.`],
 why:R`Each normal form tightens the one before it.`},
{id:'msqkeys',t:'ic',u:'keys',lv:1,k:'msq',name:'Key facts',sheet:R`\text{candidate key = minimal superkey; many possible; PK not NULL}`,
 q:R`Which statements are true?`,
 o:[R`A candidate key is a minimal superkey`,R`A relation can have several candidate keys`,R`Any superset of a superkey is a superkey`,R`A primary key may contain NULL`],a:[0,1,2],
 ex:[R`Definition.`,R`E.g. roll number and Aadhaar number.`,R`Adding attributes keeps uniqueness.`,R`Entity integrity forbids it.`],
 why:R`Minimality separates candidate keys from other superkeys.`},
{id:'msqfk',t:'ic',u:'fk',lv:2,k:'msq',name:'Foreign key facts',sheet:R`\text{FK may be NULL; refers to a key; child insert / parent delete can violate}`,
 q:R`S.x is a foreign key referencing R's primary key. Which statements are true?`,
 o:[R`S.x may be NULL unless declared NOT NULL`,R`Every non-NULL S.x value must exist in R`,R`Deleting a tuple from S can violate the constraint`,R`Inserting a tuple into S can violate the constraint`],a:[0,1,3],
 ex:[R`NULL means no reference.`,R`Referential integrity.`,R`Removing a child can't leave a dangling reference.`,R`It might point to a missing key.`],
 why:R`Violations come from new children or from removing parents.`},
{id:'msqsql',t:'rel',u:'sql',lv:1,k:'msq',name:'SQL facts',sheet:R`\text{COUNT(*) counts all rows; WHERE before grouping; HAVING after; UNION dedups}`,
 q:R`Which statements about SQL are true?`,
 o:[R`COUNT(*) counts rows even when they contain NULLs`,R`<code>WHERE COUNT(*) > 2</code> is not allowed`,R`HAVING filters groups after GROUP BY`,R`UNION keeps duplicate rows`],a:[0,1,2],
 ex:[R`It counts rows, not values.`,R`WHERE runs before grouping, so filters on the query's own aggregates go in HAVING.`,R`That is its purpose.`,R`UNION ALL keeps duplicates; UNION removes them.`],
 why:R`The logical clause order explains most SQL rules.`},
{id:'msqra',t:'rel',u:'relalg',lv:2,k:'msq',name:'Relational algebra facts',sheet:R`\pi\ \text{removes duplicates};\ \bowtie\ \text{with no common attrs}=\times;\ \sigma\ \text{cascades}`,
 q:R`Which statements are true?`,
 o:[R`Projection removes duplicate tuples`,R`A natural join of relations with no common attributes is their Cartesian product`,R`\(\sigma_{c_1\wedge c_2}(R)=\sigma_{c_1}(\sigma_{c_2}(R))\)`,R`\(R-S=S-R\)`],a:[0,1,2],
 ex:[R`Relations are sets.`,R`Nothing to match on.`,R`Selections cascade.`,R`Difference isn't symmetric.`],
 why:R`Algebra uses set semantics; SQL uses bags.`},
{id:'msqbp',t:'file',u:'index',lv:2,k:'msq',name:'B+ tree facts',sheet:R`\text{linked leaves; half-full except root; data pointers in leaves}`,
 q:R`Which statements about B+ tree indexes are true?`,
 o:[R`Leaf nodes are linked for range scans`,R`Every node except the root is at least half full`,R`A hash index handles range queries better than a B+ tree`,R`Record pointers appear only in the leaves`],a:[0,1,3],
 ex:[R`Walk the leaf chain in key order.`,R`Splits and merges keep occupancy up.`,R`Hashing destroys key order.`,R`Internal nodes only guide the search.`],
 why:R`B+ trees are the default index because they handle both equality and range queries.`},
{id:'msqdecomp',t:'norm',u:'decomp',lv:2,k:'msq',name:'Decomposition facts',sheet:R`\text{lossless if common attrs key one side; 3NF synthesis lossless + preserving}`,
 q:R`Which statements are true?`,
 o:[R`A lossless, dependency-preserving 3NF decomposition always exists`,R`Every BCNF decomposition preserves all dependencies`,R`A binary decomposition is lossless if the common attributes form a key of one part`,R`Joining the parts of a lossy decomposition can create spurious tuples`],a:[0,2,3],
 ex:[R`3NF synthesis guarantees both.`,R`AB → C, C → B can't be preserved in BCNF.`,R`That's the lossless-join test.`,R`That is what "lossy" means.`],
 why:R`3NF trades a little redundancy for dependency preservation.`},
{id:'msqolap',t:'dw',u:'olap',lv:1,k:'msq',name:'OLAP operation facts',sheet:R`\text{roll-up: coarser; drill-down: finer; slice: fix one dim; CUBE}(D_1,D_2)\text{: 4 groupings}`,
 q:R`Which statements are true?`,
 o:[R`Roll-up moves up a concept hierarchy`,R`Slice fixes one dimension to a single value`,R`Drill-down produces more aggregated data`,R`GROUP BY CUBE on two dimensions produces four groupings`],a:[0,1,3],
 ex:[R`E.g. city → state.`,R`E.g. time = Q1.`,R`It goes to finer detail.`,R`(D1, D2), (D1), (D2), ().`],
 why:R`Roll-up and drill-down are opposites.`},
{id:'msqschema',t:'dw',u:'schema',lv:1,k:'msq',name:'Warehouse schema facts',sheet:R`\text{star: 1 fact + denormalised dims; snowflake: normalised dims}`,
 q:R`Which statements are true?`,
 o:[R`A star schema has a single central fact table`,R`A snowflake schema normalises the dimension tables`,R`A fact table stores numeric measures`,R`Dimension tables store the numeric measures`],a:[0,1,2],
 ex:[R`With dimensions around it.`,R`Dimensions split into sub-tables.`,R`Plus foreign keys to the dimensions.`,R`They hold descriptive attributes.`],
 why:R`Facts are the numbers; dimensions describe them.`},
{id:'msqmeas',t:'dw',u:'measures',lv:1,k:'msq',name:'Kinds of measures',sheet:R`\text{distributive: sum, count;\ algebraic: avg;\ holistic: median}`,
 q:R`Which classifications are correct?`,
 o:[R`SUM is distributive`,R`AVG is algebraic`,R`MEDIAN is holistic`,R`COUNT is holistic`],a:[0,1,2],
 ex:[R`Add the partition sums.`,R`From (sum, count).`,R`Needs all the values.`,R`COUNT is distributive.`],
 why:R`Ask whether the measure can be combined from small summaries of each partition.`},
{id:'msqscale',t:'dt',u:'dtypes',lv:1,k:'msq',name:'Measurement scales',sheet:R`\text{nominal, ordinal, interval (no true zero), ratio}`,
 q:R`Which classifications are correct?`,
 o:[R`Temperature in °C is interval`,R`Temperature in kelvin is ratio`,R`Blood group is ordinal`,R`Rank in an exam is ordinal`],a:[0,1,3],
 ex:[R`0 °C isn't "no temperature".`,R`0 K is a true zero.`,R`It has no order: nominal.`,R`Ordered, with unequal gaps.`],
 why:R`Check whether the values have an order and whether there is a true zero.`}
]);
})();
